import{b as a,O as r,g as o,j as p}from"./chunks/framework.DSt9LnBW.js";const n=JSON.parse('{"title":"关于px em rem vh vw那些事儿","description":"前言：在做移动端响应式布局的时候发现这个知识点还是比较薄弱，记录一下","frontmatter":{"date":"2026-06-09T00:00:00.000Z","tags":["CSS","单位"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/frontend/px-em-rem-vh-vw/index.md","filePath":"个人博客/前端/18.关于px em rem vh vw那些事儿.md","lastUpdated":1789442310000}'),t={name:"blog/frontend/px-em-rem-vh-vw/index.md"};function d(l,e,c,h,i,m){return r(),o("div",null,[...e[0]||(e[0]=[p('<h1 id="关于px-em-rem-vh-vw那些事儿" tabindex="-1">关于px em rem vh vw那些事儿 <a class="header-anchor" href="#关于px-em-rem-vh-vw那些事儿" aria-label="Permalink to &quot;关于px em rem vh vw那些事儿&quot;">​</a></h1><blockquote><p>前言：在做移动端响应式布局的时候发现这个知识点还是比较薄弱，记录一下</p></blockquote><h3 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h3><h3 id="px" tabindex="-1">px <a class="header-anchor" href="#px" aria-label="Permalink to &quot;px&quot;">​</a></h3><p>绝对单位，表示像素，CSS规范的定义，CSS中的px是一个相对长度，它相对的，是viewing device的分辨率。这个viewing device，通常就是电脑显示器。就好比呈现在我们显示器上的一个个小点，每个像素点都是大小等同的。</p><h3 id="em" tabindex="-1">em <a class="header-anchor" href="#em" aria-label="Permalink to &quot;em&quot;">​</a></h3><p>相对单位，em的大小并不是固定的，一般情况下会继承父元素文字大小，相对于当前对象内文本的字体尺寸。如当前对行内文本的字体尺寸未被人为设置，则相对于浏览器的默认字体16px尺寸。</p><h3 id="rem" tabindex="-1">rem <a class="header-anchor" href="#rem" aria-label="Permalink to &quot;rem&quot;">​</a></h3><p>rem是CSS3新增的一个相对单位，与em的区别在于元素设定字体大小时，仍然是相对大小，但相对的只是HTML根元素。</p><h3 id="vh-vw" tabindex="-1">vh&amp;vw <a class="header-anchor" href="#vh-vw" aria-label="Permalink to &quot;vh&amp;vw&quot;">​</a></h3><p>都作为视口单位，vh代表的是view height，也就是显示器可视范围高度的百分比；vw表示的是view width，也就是显示器可是范围宽度的百分比， 1vw = 1% * 视口宽度 。也就是说，一个显示器视口就是 100vw</p><h2 id="vw-px-rem之间的换算" tabindex="-1">vw px rem之间的换算 <a class="header-anchor" href="#vw-px-rem之间的换算" aria-label="Permalink to &quot;vw px rem之间的换算&quot;">​</a></h2><p>以下面标准为例（受随着根元素字体大小、移动端屏幕大小影响，计算均是进行四舍五入的结果）：</p><p>移动端屏幕为<code>750px</code></p><p>那么： <code>100vw = 750px</code></p><p>所以<code>1vw</code>就等于：<code>1vw =750px/100vw = 7.5px</code></p><p>注意现在<code>1vw</code>等于 <code>7.5px</code>，而我们的<code>1rem</code>是<code>16px</code> (默认情况下 根元素字体大小为<code>16</code>px)</p><p>现在进行计算：<code>1rem = 16px/7.5px = 2.133vw</code></p><p>相反：<code>1vw = 7.5px/16px = 0.469rem</code></p><p>上面的计算公式计算同样也可以逆向思考下：</p><p>同理，移动端屏幕大小为<code>750px</code></p><p>我们计算<code>1px</code>等于多少<code>vw</code>: <code>1px = 100/750 = 0.1333vw</code></p><p>显示<code>1px=0.1333vw</code></p><p>现在进行计算：<code>1rem= 0.1333 * 16 = 2.133vw</code></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>px 跟设备像素走，em 跟当前字体走，rem 只跟根字体走，vw / vh 跟视口走。移动端常用「根字体 + rem」或「vw 换算 rem」，先定设计稿宽度再算比例。</p><div class="blog-refs"><p>参考资料</p><ul><li><a href="https://github.com/Qingquan-Li/blog/issues/58" target="_blank" rel="noreferrer">物理像素和逻辑像素</a></li><li><a href="https://pjchender.blogspot.com/2015/04/css-3vh-vw.html" target="_blank" rel="noreferrer">好用的 CSS3 单位 vh vw</a></li><li><a href="https://segmentfault.com/a/1190000016047555" target="_blank" rel="noreferrer">移动端 vw / px / rem 换算</a></li></ul></div>',27)])])}const s=a(t,[["render",d]]);export{n as __pageData,s as default};
